  'compliance-p1' => 'स्वास्थ्य देखभाल संगठनों को HIPAA का अनुपालन करना होगा। दस्तावेज़ सुरक्षित होने चाहिए, पहुंच लॉग होनी चाहिए, और HIPAA द्वारा निर्दिष्ट अवधारण अवधि का पालन किया जाना चाहिए।',
  'compliance-p2' => 'वित्तीय सेवा संगठनों को एसईसी और अवधारण अवधि निर्दिष्ट करने वाले अन्य नियमों का पालन करना होगा। आवश्यक दस्तावेज़ों को बनाए रखने में विफलता दायित्व पैदा करती है।',
  'compliance-p3' => 'मुकदमेबाजी दस्तावेजों का प्रबंधन करने वाले कानूनी संगठनों को यह सुनिश्चित करना चाहिए कि दस्तावेजों को ठीक से संरक्षित किया जाए। लूट-पाट कानून प्रासंगिक दस्तावेज़ों को नष्ट करने से मना करते हैं।',
  'compliance-p4' => 'अपने संगठन पर लागू नियमों को समझें. विभिन्न उद्योगों की अलग-अलग अवधारण आवश्यकताएँ होती हैं।',
  'cost-heading' => 'लागत प्रबंधन',
  'cost-p1' => 'बड़े दस्तावेज़ों को संग्रहित करना महंगा है। संपीड़न और डिडुप्लीकेशन के माध्यम से लागत कम करें।',
  'cost-p2' => 'संपीड़न भंडारण आवश्यकताओं को पचास से सत्तर प्रतिशत तक कम कर देता है। संपीड़ित अभिलेखों को संग्रहीत करने में काफी कम लागत आती है।',
  'cost-p3' => 'डिडुप्लीकेशन डुप्लिकेट दस्तावेज़ों को हटा देता है। संगठन अक्सर एक ही दस्तावेज़ की कई प्रतियाँ संग्रहित करते हैं। डुप्लिकेट हटाने से भंडारण लागत कम हो जाती है।',
  'cost-p4' => 'स्तरीय भंडारण से लागत कम हो जाती है। महँगे सक्रिय भंडारण में हाल के दस्तावेज़। सस्ते अभिलेखीय भंडारण में पुराने दस्तावेज़।',
  'cost-p5' => 'प्रति दस्तावेज़ लागत की गणना करें. भंडारण लागत को समझना संग्रह प्रबंधन निर्णयों का मार्गदर्शन करता है।',
  'disaster-heading' => 'आपदा पुनर्प्राप्ति',
  'disaster-p1' => 'पुरालेख विफलता संकट पैदा करती है. आपदा निवारण हेतु योजना बनायें।',
  'disaster-p2' => 'विभिन्न स्थानों पर अनेक प्रतियाँ बनाए रखें। यदि एक स्थान विफल हो जाता है, तो बैकअप पहुंच योग्य रहता है।',
  'disaster-p3' => 'पुनर्प्राप्ति प्रक्रियाओं का नियमित रूप से परीक्षण करें। सैद्धांतिक पुनर्प्राप्ति योजनाएँ जो व्यवहार में विफल हो जाती हैं, बेकार हैं।',
  'disaster-p4' => 'दस्तावेज़ पुनर्प्राप्ति प्रक्रियाएँ. बैकअप अभिलेखागार तक पहुँचने के लिए टीमों को स्पष्ट निर्देशों की आवश्यकता है।',
  'disaster-p5' => 'पुनर्प्राप्ति समय उद्देश्यों की गणना करें। अभिलेखों को कितनी जल्दी पुनर्स्थापित किया जाना चाहिए? यह बैकअप रणनीति निर्धारित करता है.',
  'strategy-heading' => 'दीर्घकालिक संरक्षण रणनीति',
  'strategy-p1' => 'दीर्घकालिक संरक्षण रणनीति विकसित करें। इस रणनीति को प्रारूप संरक्षण, मीडिया अप्रचलन, मेटाडेटा संरक्षण और पहुंच निरंतरता को संबोधित करना चाहिए।',
  'strategy-p2' => 'संरक्षण नीतियां स्थापित करें. अवधारण अवधि, अभिगम नियंत्रण और अभिलेखीय प्रक्रियाओं को परिभाषित करें।',
  'strategy-p3' => 'अभिलेखीय कार्यों के लिए बजट. संग्रह करने में पैसे खर्च होते हैं. संगठनों को चल रहे अभिलेखीय खर्चों का बजट बनाना चाहिए।',
  'strategy-p4' => 'अभिलेखीय कर्मचारियों को प्रशिक्षित करें। संग्रह का प्रबंधन करने वाले पुरालेखपालों को विशेष ज्ञान की आवश्यकता होती है।',
  'strategy-p5' => 'संरक्षण रणनीति को चालू रखें. प्रौद्योगिकी और नियम विकसित होते हैं। संरक्षण रणनीति को समय-समय पर अद्यतन करें।',
  'integration-heading' => 'दस्तावेज़ वर्कफ़्लोज़ के साथ एकीकरण',
  'integration-p1' => 'पुरालेख प्रणालियों को दस्तावेज़ प्रसंस्करण वर्कफ़्लो के साथ एकीकृत होना चाहिए। जब दस्तावेज़ अभिलेखीय आयु तक पहुँच जाते हैं, तो उन्हें स्वचालित रूप से अभिलेखीय भंडारण में ले जाना चाहिए। __MERGE_LINK__ संबंधित संग्रहीत दस्तावेज़ों को व्यवस्थित सेटों में संग्रहित करने से संग्रह संगठन और पुनर्प्राप्ति में सुधार होता है। उन पुरालेखों के लिए जिन्हें विश्लेषण या पुनर्प्रयोजन की आवश्यकता होती है, __CONVERT_LINK__ संग्रहित दस्तावेजों को संपादन योग्य प्रारूपों में संग्रहित अखंडता से समझौता किए बिना संभव होना चाहिए।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-p1' => 'पीडीएफ संग्रह दीर्घकालिक पहुंच के लिए संगठनात्मक दस्तावेजों को संरक्षित करता है। उचित तैयारी, उचित भंडारण समाधान और स्पष्ट संगठन यह सुनिश्चित करते हैं कि अभिलेख मूल्यवान बने रहें।',
  'conclusion-p2' => 'लंबे समय तक प्रतिधारण आवश्यकताओं वाले दस्तावेज़ों के लिए पीडीएफ/ए प्रारूप का उपयोग करें। भंडारण लागत कम करने के लिए दस्तावेज़ों को संपीड़ित करें। अच्छे मेटाडेटा के साथ व्यवस्थित भंडारण लागू करें।',
  'conclusion-p3' => 'बड़े अभिलेखों के लिए, पेशेवर डिजिटल परिसंपत्ति प्रबंधन प्रणालियों का उपयोग करें। ये सिस्टम मजबूत खोज और पहुंच नियंत्रण प्रदान करते हुए लाखों दस्तावेज़ों तक पहुंचते हैं।',
  'conclusion-p4' => 'अभिलेखीय और पुनर्प्राप्ति प्रक्रियाओं का नियमित रूप से परीक्षण करें। संग्रहण तभी सफल होता है जब आवश्यकता पड़ने पर दस्तावेज़ पुनः प्राप्त किए जा सकें।',
  'conclusion-p5' => 'विभिन्न स्थानों पर अनेक प्रतियाँ बनाए रखें। अतिरेक भंडारण विफलताओं और डेटा हानि से बचाता है।',
);
